class CreateJobDialogController{constructor($scope,$mdDialog,DispatchData,toastrService,loadingService,$http,$document,staffId){this.$scope=$scope;this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.$http=$http;this.toastrService=toastrService;this.loadingService=loadingService;this.$document=$document;this.staffId=staffId;this.jobForm=$scope.jobForm;this.fromAddressSearchText="";this.toAddressSearchText="";this.searchClientText="";this.selectedClient=null;this.selectedFromAddress=null;this.selectedToAddress=null;this.selectedSpeed=null;this.speedOptions=[];DispatchData.getSpeedList().then(data=>{this.speedOptions=data});this.jobDate=new Date;this.jobDate.setDate(this.jobDate.getDate()+1);this.job={}}async clientSearchAutocomplete(searchTerm){const url="/home/ActiveClients";try{return await this.DispatchData.autocompleteSearch(searchTerm,url)}catch(error){this.toastrService.showErrorToast(error.message)}}async addressSearchAutocomplete(searchText){try{const suggestions=await this.DispatchData.autocompleteAddressSearch(searchText);return this.transformSuggestions(suggestions)}catch(error){this.toastrService.showErrorToast(error.message)}}transformSuggestions(data){return data.suggestions.map(obj=>({id:obj.locationId,text:obj.label.split(", ").reverse().join(", ")}))}async findSuburbByDistrict(district){const ourSuburbs=await this.DispatchData.getSuburbList();let lowerCaseDistrict=district.toLowerCase();return ourSuburbs.find(localSuburb=>localSuburb.text.toLowerCase()===lowerCaseDistrict||localSuburb.alias&&localSuburb.alias.toLowerCase()===lowerCaseDistrict)}async addressSearchItemSelected(item,toAddress){try{const data=await this.DispatchData.getGeoCodeInformation(item);const returnedLocation=data.Response.View[0].Result[0].Location;const mappedSub=await this.findSuburbByDistrict(returnedLocation.Address.District);if(mappedSub!==undefined){console.log(mappedSub);if(toAddress){this.job.toSuburb=mappedSub.text}else{this.job.fromSuburb=mappedSub.text}}}catch(error){console.log("Error: ",error)}}async submit(event,job){try{if(!this.jobForm.$valid){this.$mdDialog.show(this.$mdDialog.alert().parent(angular.element(this.$document.body)).clickOutsideToClose(true).title("Required Fields").textContent("Please complete all the required fields.").ariaLabel("Not all required fields are completed").ok("Got it!").targetEvent(event));return}job.clientID=this.selectedClient.id;job.fromAddress=this.selectedFromAddress.text;job.toAddress=this.selectedToAddress.text;job.date=this.jobDate.toISOString();job.speedId=this.selectedSpeed.id;const response=await this.createJob(job);const newJobId=response.data.jobId;this.toastrService.showSuccessToast("New Job Created Successfully");this.$mdDialog.hide(newJobId)}catch(error){this.toastrService.showErrorToast(error.message)}}async createJob(job){try{const url="job/QuickCreateJob/";const callData={job:job,staffId:this.staffId};return await this.$http.post(url,callData,{headers:{"Content-Type":"application/json"}})}catch(error){this.toastrService.showErrorToast(error.message)}}cancel(){this.$mdDialog.cancel()}}